<template>
<ElConfigProvider namespace="kel"><div class="keel-kestra jp-app">
 <aside class="jp-sidebar">
  <a class="jp-brand" href="#flows"><span class="jp-brand-mark">k</span><strong>keel<span>.</span></strong><span class="jp-env">DEV</span></a>
  <button class="jp-side-search" @click="searchOpen=true"><Magnify :size="17"/><span>搜索工作区</span><kbd>⌘ K</kbd></button>
  <nav class="jp-job-nav" aria-label="作业平台导航"><div class="jp-nav-label">作业平台</div><button :class="{active:page==='flows'||page==='editor'}" :aria-current="page==='flows'||page==='editor'?'page':undefined" @click="go('flows')"><TransitConnectionVariant :size="18"/><span>Flows</span><span class="jp-nav-count">{{projectFlows.length}}</span></button><button :class="{active:page==='executions'||page==='execution'}" :aria-current="page==='executions'||page==='execution'?'page':undefined" @click="go('executions')"><PlayOutline :size="18"/><span>Executions</span><span v-if="runCreated" class="jp-live-dot"/></button><button :class="{active:page==='agents'}" :aria-current="page==='agents'?'page':undefined" @click="go('agents')"><ServerOutline :size="18"/><span>Agents</span><span class="jp-nav-count">{{agentRows.length}}</span></button></nav>
  <div class="jp-sidebar-bottom"><div class="jp-preview-label"><FlaskOutline :size="15"/><span>交互设计预览</span><span class="jp-small-dot"/></div></div>
 </aside>
 <div class="jp-body">
  <header class="jp-topbar"><div class="jp-breadcrumb"><span>运维中心</span><ChevronRight :size="13"/><span>作业平台</span><template v-if="page!=='flows'"><ChevronRight :size="13"/><strong>{{page==='editor'?currentFlow.name:page==='execution'?'Execution':page==='agents'?'Agents':'Executions'}}</strong></template></div><div class="jp-top-actions"><span class="jp-synthetic">SYNTHETIC PREVIEW</span><button class="jp-icon-button" aria-label="切换主题" @click="toggleTheme"><component :is="dark?WhiteBalanceSunny:WeatherNight" :size="18"/></button><div class="jp-notifications"><button class="jp-icon-button" aria-label="通知" @click="notifications=!notifications"><BellOutline :size="18"/><i/></button><div v-if="notifications" class="jp-popover"><b>通知中心</b><p>2 台设备的拓扑检查需要处理</p><button @click="go('execution');notifications=false">查看演示执行 →</button></div></div><div class="jp-top-separator"/><div class="jp-project-label"><small>当前项目</small><select aria-label="项目切换" v-model="project"><option>B300 · POD-A</option><option>B300 · POD-B</option><option>所有授权项目</option></select></div><span class="jp-avatar small">YZ</span></div></header>
  <main class="jp-main">
  <template v-if="page==='flows'">
   <div class="jp-page-heading"><div><div class="jp-title-line"><h1>作业平台</h1><span class="jp-count">{{projectFlows.length}}</span></div><p>编排交付任务，追踪每一次执行。</p></div><div class="jp-actions"><KsButton @click="openRun()"><LightningBoltOutline :size="16"/>Quick Run</KsButton><KsButton type="primary" @click="createFlow"><Plus :size="16"/>创建 Flow</KsButton></div></div>
   <div class="jp-viewbar"><div class="jp-tabs"><button :class="{active:!flowState}" @click="flowState=''">全部 Flows</button><button :class="{active:flowState==='ENABLED'}" @click="flowState='ENABLED'">已启用 <span>{{projectFlows.filter(f=>f.state==='ENABLED').length}}</span></button><button :class="{active:flowState==='DRAFT'}" @click="flowState='DRAFT'">草稿 <span>{{projectFlows.filter(f=>f.state==='DRAFT').length}}</span></button></div><button class="jp-save-view" @click="saveView">{{viewSaved?'✓ 已保存当前视图':'保存视图'}}</button></div>
   <div class="jp-filters"><KsInput v-model="query" placeholder="搜索 Flow 名称、ID 或 Namespace" clearable/><select v-model="namespace" aria-label="Namespace筛选"><option value="">所有 Namespace</option><option v-for="n in namespaces" :key="n">{{n}}</option></select><select v-model="targetFilter" aria-label="目标类型筛选"><option value="">所有目标类型</option><option>GPU Server</option><option>Switch</option><option>Server</option><option>Mixed</option></select><select v-model="flowState" aria-label="Flow状态筛选"><option value="">所有状态</option><option>ENABLED</option><option>DRAFT</option><option>DISABLED</option></select><button v-if="query||namespace||flowState||targetFilter" class="jp-clear" @click="clearFilters">清除</button><span class="jp-grow"/><KsButton size="small" @click="refresh"><Refresh :size="16"/></KsButton><KsButton size="small" @click="columnsOpen=!columnsOpen"><ViewColumnOutline :size="16"/>列</KsButton><div v-if="columnsOpen" class="jp-column-pop"><label><input type="checkbox" v-model="showDescription"/>描述</label><label><input type="checkbox" v-model="showSchedule"/>触发方式</label><label><input type="checkbox" v-model="showUpdated"/>更新时间</label></div></div>
   <div v-if="selectedRows.length" class="jp-selection"><b>已选择 {{selectedRows.length}} 个 Flow</b><KsButton size="small" @click="batchState('DISABLED')">停用所选</KsButton><KsButton size="small" @click="batchState('ENABLED')">启用所选</KsButton><span class="jp-muted">仅更新原型内存</span></div>
   <div class="jp-catalog"><KsDataTable :data="pagedFlows" :selectable="true" :total="filteredFlows.length" v-model:currentPage="pageNumber" :pageSize="10" :pageSizeOptions="[10]" :loading="loading" :fitHeight="true" rowKey="id" :loadData="loadPage" @sort-change="sort=>sortOrder=sort.order||''" @selection-change="rows=>selectedRows=rows" @row-click="row=>openFlow(row)">
    <KsTableColumn label="名称 / Flow ID" minWidth="250" sortable="custom" prop="name" :sortOrders="['ascending','descending']"><template #default="{row}"><div class="jp-flow-name"><span class="jp-flow-icon"><TransitConnectionVariant :size="18"/></span><div><button class="jp-row-title" @click.stop="openFlow(row)">{{row.name}}</button><code>{{row.id}}</code></div></div></template></KsTableColumn>
    <KsTableColumn label="Namespace" minWidth="150"><template #default="{row}"><span class="jp-namespace">{{row.namespace}}</span><small v-if="showDescription">{{row.description}}</small></template></KsTableColumn>
    <KsTableColumn label="目标" width="115"><template #default="{row}"><span class="jp-target-tag"><component :is="row.target==='Switch'?Switch:ServerOutline" :size="13"/>{{row.target}}</span></template></KsTableColumn>
    <KsTableColumn v-if="showSchedule" label="触发方式" width="150"><template #default="{row}"><span class="jp-inline"><ClockOutline v-if="row.cron!=='手动'" :size="14"/><CursorDefaultOutline v-else :size="14"/>{{row.cron}}</span></template></KsTableColumn>
    <KsTableColumn label="最近执行" width="144"><template #default="{row}"><div v-if="row.history.length" class="jp-run-bars"><button v-for="(state,i) in row.history" :key="i" :class="state.toLowerCase()" :title="state+' · 点击查看执行'" @click.stop="go('execution')"/><small>{{row.history.at(-1)==='RUNNING'?'正在运行':'14:32 · 24.4s'}}</small></div><span v-else class="jp-muted">尚未执行</span></template></KsTableColumn>
    <KsTableColumn label="状态" width="105"><template #default="{row}"><span :class="['jp-flow-state',row.state.toLowerCase()]"><i/>{{{ENABLED:'已启用',DISABLED:'已停用',DRAFT:'草稿'}[row.state]}}</span></template></KsTableColumn>
    <KsTableColumn v-if="showUpdated" label="更新" width="100"><template #default="{row}"><span class="jp-muted">{{row.updated}}</span><small>rev {{row.revision}}</small></template></KsTableColumn>
    <KsTableColumn label="" width="70"><template #default="{row}"><button class="jp-icon-button jp-run-button" :disabled="row.state!=='ENABLED'" aria-label="运行Flow" title="运行此Flow" @click.stop="openRun(row)"><PlayOutline :size="20"/></button></template></KsTableColumn>
   </KsDataTable></div>
   <div class="jp-bottom-line"><span><span class="jp-small-dot"/>{{filteredFlows.length}} 个 Flow · {{project}}</span><span>Namespace 隔离 · 版本化定义 · 授权执行</span></div>
  </template>
  <template v-else-if="page==='editor'">
   <div class="jp-detail-heading"><button class="jp-icon-button jp-back" aria-label="返回Flow目录" @click="go('flows')"><ArrowLeft :size="20"/></button><div><div class="jp-title-line"><h1>{{currentFlow.name}}</h1><span class="jp-flow-state enabled"><i/>{{dirty?'未保存更改':'已启用'}}</span></div><div class="jp-subtitle"><code>{{currentFlow.namespace}} / {{currentFlow.id}}</code><span>Revision {{revision}}</span></div></div><span class="jp-grow"/><KsButton @click="validate"><Check :size="16"/>校验</KsButton><KsButton :disabled="!dirty" @click="saveDraft"><ContentSaveOutline :size="16"/>保存草稿</KsButton><KsButton v-if="currentFlow.state==='DRAFT'" :disabled="dirty" @click="currentFlow.state='ENABLED';notify('演示Flow已发布')">发布草稿</KsButton><KsButton type="primary" :disabled="dirty||currentFlow.state!=='ENABLED'" @click="openRun(currentFlow)"><PlayOutline :size="17"/>运行</KsButton></div>
   <div class="jp-context-tabs"><button v-for="t in ['Overview','Builder','Executions','Revisions','Triggers']" :key="t" :class="{active:tab===t}" @click="setTab(t)">{{t}}</button><span class="jp-grow"/><span class="jp-muted">最后修改 · 演示用户</span></div>
   <div v-if="validation" :class="['jp-feedback',validation.startsWith('✓')?'success':'error']">{{validation}}<button @click="validation=''">×</button></div>
   <EditorPreview v-if="tab==='Builder'" :source="yamlSource" :theme="dark?'dark':'light'" :selected="selectedTask" @select="id=>selectedTask=id" @change="updateSource" @save="saveDraft"/>
   <div v-else-if="tab==='Overview'" class="jp-flow-overview"><section><div class="jp-section-title"><h3>Flow 定义</h3><KsButton size="small" @click="setTab('Builder')">打开编辑器 →</KsButton></div><p>{{currentFlow.description}}</p><dl class="jp-kv"><dt>Namespace</dt><dd>{{currentFlow.namespace}}</dd><dt>Flow ID</dt><dd><code>{{currentFlow.id}}</code></dd><dt>版本</dt><dd>{{revision}}</dd><dt>目标类型</dt><dd>{{currentFlow.target}}</dd><dt>触发方式</dt><dd>{{currentFlow.cron}}</dd><dt>来源</dt><dd>Synthetic design fixture</dd></dl><div class="jp-section-title"><h3>最近执行</h3><button class="jp-text-link" @click="go('execution')">查看详情 →</button></div><div class="jp-recent-run"><KsExecutionStatus status="FAILED" size="small"/><code>demo-exec-8f2a</code><span>32 targets</span><span>24.4s</span><span>revision 12</span></div></section><aside class="jp-outline"><h3>任务结构</h3><button v-for="(t,i) in editorTasks" :key="t.id" @click="selectedTask=t.id;setTab('Builder')"><span>{{i+1}}</span><div><b>{{t.id}}</b><small>{{t.type.split('.').at(-1)}}</small></div><ChevronRight :size="16"/></button></aside></div>
   <div v-else-if="tab==='Revisions'" class="jp-revisions"><aside><h3>版本历史</h3><button v-for="r in [12,11,10,9]" :key="r" :class="{active:diffRevision===r}" @click="diffRevision=r"><b>Revision {{r}}</b><span v-if="r===12">当前版本</span><small>{{r===12?'6 分钟前':'2026-10-'+(r+15)}} · 演示用户</small></button></aside><section><div class="jp-section-title"><h3>Revision {{diffRevision}} → 当前草稿</h3><KsButton size="small" @click="restoreRevision">恢复为新草稿</KsButton></div><div class="jp-diff-head"><span>修改前</span><span>修改后</span></div><div class="jp-diff-code"><pre>timeout: PT5M\nconcurrencyLimit: 4\nmaxAttempts: 1</pre><pre>timeout: PT10M\nconcurrencyLimit: 8\nmaxAttempts: 2</pre></div><small class="jp-muted">原型差异样例 · 恢复操作只生成当前页面草稿</small></section></div>
   <div v-else-if="tab==='Triggers'" class="jp-triggers"><div class="jp-section-title"><h3>触发器</h3><KsButton @click="triggerDialog=true"><Plus :size="16"/>添加 Schedule</KsButton></div><div v-for="(t,i) in schedules" :key="i" class="jp-trigger-row"><ClockOutline :size="22"/><div><b>{{t.id}}</b><small>{{t.cron}} · UTC</small></div><span class="jp-target-tag">Schedule</span><span class="jp-grow"/><span :class="['jp-flow-state',t.enabled?'enabled':'disabled']"><i/>{{t.enabled?'已启用':'已停用'}}</span><KsButton size="small" @click="t.enabled=!t.enabled;dirty=true">{{t.enabled?'停用草稿':'启用草稿'}}</KsButton></div><p class="jp-muted">修改仅保留在原型草稿中，不创建真实定时任务。</p></div>
   <div v-else class="jp-inner-executions"><ExecutionList @open="openExecution"/></div>
  </template>
  <template v-else-if="page==='executions'">
   <div class="jp-page-heading"><div><div class="jp-title-line"><h1>Executions</h1><span class="jp-count">8</span></div><p>每一次执行，均可追踪到任务、设备与证据。</p></div><KsButton @click="refresh"><Refresh :size="16"/>刷新</KsButton></div>
   <div class="jp-viewbar"><div class="jp-tabs"><button :class="{active:execFilter==='all'}" @click="execFilter='all'">全部记录</button><button :class="{active:execFilter==='running'}" @click="execFilter='running'">运行中 <span>1</span></button><button :class="{active:execFilter==='failed'}" @click="execFilter='failed'">需要关注 <span>2</span></button></div><span class="jp-muted">最近 24 小时</span></div><div class="jp-exec-summary"><span><i class="jp-small-dot"/>8 次执行</span><span class="jp-success">5 成功</span><span class="jp-danger">2 失败</span><span class="jp-purple">1 运行中</span><span class="jp-grow"/><span>设备结果与引擎状态独立展示</span></div><ExecutionList :filter="execFilter" @open="openExecution"/>
  </template>
  <template v-else-if="page==='execution'">
   <div class="jp-detail-heading"><button class="jp-icon-button jp-back" aria-label="返回执行目录" @click="go('executions')"><ArrowLeft :size="20"/></button><div><div class="jp-title-line"><h1>{{currentFlow.name}}</h1><KsExecutionStatus :status="execState" size="small"/></div><div class="jp-subtitle"><code>{{executionID}}</code><span>Revision {{revision}}</span><span>手动触发 · 演示用户</span></div></div><span class="jp-grow"/><KsButton v-if="['RUNNING','PAUSED'].includes(execState)" @click="confirmAction=execState==='PAUSED'?'resume':'pause'"><component :is="execState==='PAUSED'?PlayOutline:Pause" :size="16"/>{{execState==='PAUSED'?'继续':'暂停'}}</KsButton><KsButton v-if="['RUNNING','PAUSED'].includes(execState)" @click="confirmAction='kill'"><StopCircleOutline :size="16"/>终止</KsButton><KsButton @click="showDefinition"><CodeTags :size="16"/>源版本</KsButton><KsButton type="primary" @click="confirmAction=execState==='FAILED'?'retry':'rerun'"><Refresh :size="16"/>{{execState==='FAILED'?'重试失败目标':'重新运行'}}</KsButton></div>
   <div class="jp-execution-meta"><div><small>开始时间</small><strong>14:32:06 <span>2026-11-01</span></strong></div><div><small>运行耗时</small><strong>{{execState==='RUNNING'?'进行中':'24.4'}}<span v-if="execState!=='RUNNING'">秒</span></strong></div><div><small>目标结果</small><strong class="jp-result-summary"><i class="success"/>{{targetCounts.success}} <i class="failed"/>{{targetCounts.failed}} <i class="blocked"/>{{targetCounts.blocked}}</strong></div><div><small>执行通道</small><strong>Agent <span>{{executionTargets.filter(t=>t.transport==='AGENT').length}}</span> / SSH <span>{{executionTargets.filter(t=>t.transport==='SSH').length}}</span></strong></div><div class="jp-meta-timeline"><small>状态历史</small><div class="jp-state-line"><span>Created</span><i/><span>Running</span><i/><b :class="execState==='FAILED'?'jp-danger':'jp-purple'">{{execState}}</b></div></div></div>
   <div class="jp-context-tabs"><button v-for="t in ['Overview','Targets','Gantt / Tasks','Logs','Variables & Outputs','Audit / Context']" :key="t" :class="{active:tab===t}" @click="setTab(t)">{{t}}</button></div>
   <div v-if="tab==='Overview'||tab==='Gantt / Tasks'" class="jp-execution-workspace"><section class="jp-task-workspace"><div class="jp-section-title"><div class="jp-segment"><button :class="{active:taskView==='Gantt'}" @click="taskView='Gantt'">Gantt</button><button :class="{active:taskView==='Topology'}" @click="taskView='Topology'">Topology</button></div><span class="jp-muted">4 tasks · 24.4s</span></div><div v-if="taskView==='Gantt'" class="jp-gantt"><div class="jp-gantt-axis"><span>Task</span><div><span>0s</span><span>5s</span><span>10s</span><span>15s</span><span>20s</span><span>25s</span></div></div><button v-for="t in runtimeTasks" :key="t.id" :class="['jp-gantt-row',{selected:selectedTask===t.id}]" @click="selectedTask=t.id"><span class="jp-gantt-name"><component :is="t.state==='SUCCESS'?CheckCircleOutline:t.state==='FAILED'?CloseCircleOutline:ClockOutline" :size="16" :class="t.state.toLowerCase()"/><span><b>{{t.id}}</b><small>{{t.label}}</small></span></span><div class="jp-gantt-track"><i :class="t.state.toLowerCase()" :style="{left:(t.start/26*100)+'%',width:Math.max(2,t.duration/26*100)+'%'}">{{t.duration?t.duration+'s':'—'}}</i></div></button><div class="jp-gantt-footer"><span><i class="jp-small-dot success"/>成功</span><span><i class="jp-small-dot failed"/>失败</span><span><i class="jp-small-dot blocked"/>阻断</span><span class="jp-grow"/><small>点击任务查看 Attempt 与日志</small></div></div><div v-else class="jp-execution-topology"><button v-for="t in runtimeTasks" :key="t.id" :class="['jp-runtime-node',t.state.toLowerCase(),{selected:selectedTask===t.id}]" @click="selectedTask=t.id"><component :is="t.state==='SUCCESS'?CheckCircleOutline:t.state==='FAILED'?CloseCircleOutline:ClockOutline" :size="22"/><b>{{t.id}}</b><small>{{t.label}}</small><span>{{t.state}}</span></button></div><div class="jp-inline-log"><div class="jp-section-title"><h3>任务日志 <code>{{selectedTask}}</code></h3><button class="jp-text-link" @click="setTab('Logs')">展开日志 →</button></div><div v-for="(line,i) in taskLogs" :key="i" class="jp-log-line"><time>{{line[0]}}</time><span :class="line[1].toLowerCase()">{{line[1]}}</span><code>{{line[3]}}</code></div></div></section><aside class="jp-task-detail"><div class="jp-panel-caption"><span>TASK RUN</span><KsExecutionStatus :status="selectedRuntimeTask.state==='BLOCKED'?'CREATED':selectedRuntimeTask.state" size="small"/></div><h3>{{selectedTask}}</h3><p>{{selectedRuntimeTask.description}}</p><dl class="jp-kv"><dt>Task Run</dt><dd><code>demo-tr-{{selectedTask.slice(0,8)}}</code></dd><dt>开始时间</dt><dd>14:32:21.028</dd><dt>持续时间</dt><dd>{{selectedRuntimeTask.duration}} s</dd><dt>Attempts</dt><dd>{{selectedRuntimeTask.state==='FAILED'?2:1}}</dd><dt>执行版本</dt><dd>revision {{revision}}</dd></dl><h4>Attempts</h4><button v-for="a in (selectedRuntimeTask.state==='FAILED'?2:1)" :key="a" :class="['jp-attempt',{active:attempt===a}]" @click="attempt=a"><span>#{{a}} <small>{{a===1?'首次执行':'重试'}}</small></span><KsExecutionStatus :status="selectedRuntimeTask.state==='BLOCKED'?'CREATED':selectedRuntimeTask.state" size="small"/></button><div v-if="selectedRuntimeTask.state==='FAILED'" class="jp-failure-box"><b>Topology mismatch</b><p>gpu-a17 的 NIC 5 BDF 与基线不一致，另一个目标缺少必需证据。</p><button @click="setTab('Targets');selectedTarget=targets[16]">定位受影响设备 →</button></div><button class="jp-text-link" @click="setTab('Logs')">查看 Attempt {{attempt}} 日志 →</button></aside></div>
   <div v-else-if="tab==='Targets'" class="jp-targets-view"><section><div class="jp-filters"><KsInput v-model="targetSearch" placeholder="搜索设备或机柜" clearable/><select v-model="targetState"><option value="">全部结果</option><option>FAILED</option><option>SUCCESS</option><option>BLOCKED</option></select><div class="jp-segment"><button :class="{active:targetView==='matrix'}" @click="targetView='matrix'">矩阵</button><button :class="{active:targetView==='table'}" @click="targetView='table'">列表</button></div><span class="jp-grow"/><span>{{filteredTargets.length}} 台设备</span></div><div v-if="targetView==='matrix'" class="jp-target-matrix"><button v-for="t in filteredTargets" :key="t.id" :class="[t.state.toLowerCase(),{selected:selectedTarget?.id===t.id}]" @click="selectedTarget=t"><ServerOutline :size="21"/><b>{{t.name}}</b><small>{{t.rack}} · {{t.transport}}</small><span>{{t.state}}</span></button></div><KsDataTable v-else :data="pagedTargets" :fitHeight="true" :total="filteredTargets.length" :selectable="false" v-model:currentPage="targetPage" v-model:pageSize="targetPageSize" :pageSizeOptions="[10,25,50]" rowKey="id" @row-click="t=>selectedTarget=t"><KsTableColumn prop="name" label="设备"/><KsTableColumn prop="rack" label="机柜"/><KsTableColumn prop="transport" label="通道"/><KsTableColumn prop="state" label="结果"/><KsTableColumn prop="elapsed" label="耗时"/></KsDataTable></section><aside class="jp-task-detail"><div class="jp-panel-caption">TARGET DETAIL</div><h3>{{selectedTarget?.name||'选择目标设备'}}</h3><template v-if="selectedTarget"><span :class="['jp-flow-state',selectedTarget.state.toLowerCase()]"><i/>{{selectedTarget.state}}</span><dl class="jp-kv"><dt>Asset ID</dt><dd><code>{{selectedTarget.id}}</code></dd><dt>机柜</dt><dd>{{selectedTarget.rack}}</dd><dt>实际通道</dt><dd>{{selectedTarget.transport}}</dd><dt>退出码</dt><dd>{{selectedTarget.exit??'未执行'}}</dd><dt>耗时</dt><dd>{{selectedTarget.elapsed}}</dd></dl><h4>标准输出</h4><pre class="jp-target-output">{{selectedTarget.state==='SUCCESS'?'[OK] Evidence collected\n[OK] Topology matched':selectedTarget.state==='FAILED'?'[ERROR] Required topology evidence does not match baseline':'Blocked by incomplete evidence'}}</pre><button class="jp-text-link" @click="selectedTask='validate_topology';setTab('Logs')">查看对应任务日志 →</button></template></aside></div>
   <div v-else-if="tab==='Logs'" class="jp-logs-view"><div class="jp-filters"><KsInput v-model="logSearch" placeholder="搜索日志内容" clearable/><select v-model="logLevel"><option value="">所有等级</option><option>ERROR</option><option>WARN</option><option>INFO</option></select><select v-model="logTask"><option value="">所有任务</option><option v-for="t in runtimeTasks" :key="t.id">{{t.id}}</option></select><span class="jp-grow"/><button :class="['jp-follow',{active:follow}]" @click="follow=!follow"><span class="jp-small-dot"/>{{follow?'跟随日志':'已暂停跟随'}}</button><KsButton size="small" @click="downloadLogs">下载日志</KsButton></div><div class="jp-log-column-header"><span>时间</span><span>等级</span><span>任务 / 消息</span></div><div v-for="(line,i) in filteredLogs" :key="i" class="jp-log-line expanded"><time>{{line[0]}}</time><span :class="line[1].toLowerCase()">{{line[1]}}</span><div><button @click="selectedTask=line[2];setTab('Gantt / Tasks')">{{line[2]}}</button><code>{{line[3]}}</code></div></div><div v-if="!filteredLogs.length" class="jp-empty">没有匹配日志，调整筛选后查看。</div><div class="jp-log-end">— {{filteredLogs.length}} 条演示日志 · 不订阅真实日志流 —</div></div>
