function openRun(flow:FlowRow|null=null){runFlow.value=flow;runStep.value=0;runOpen.value=true;if(flow)runName.value=flow.name}
function startRun(){runOpen.value=false;runCreated.value=true;execState.value='RUNNING';selectedTask.value='collect_inventory';selectedTarget.value=null;executionID.value='demo-exec-'+Date.now().toString(36);auditEvents.value.unshift('启动演示执行：'+runTargets.value.length+' 台目标');go('execution')}
function applyAction(){const a=confirmAction.value;if(a==='pause')execState.value='PAUSED';if(a==='resume')execState.value='RUNNING';if(a==='kill')execState.value='KILLED';if(a==='retry'||a==='rerun'){runCreated.value=true;execState.value='RUNNING';selectedTask.value='collect_inventory';selectedTarget.value=null;executionID.value='demo-exec-'+Date.now().toString(36);runTargets.value=a==='retry'?targets.filter(t=>t.state==='FAILED').map(t=>t.id):targets.map(t=>t.id)}auditEvents.value.unshift(actionLabel.value+' · '+executionID.value);confirmAction.value=''}
function download(text:string,name:string,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),100)}
function downloadLogs(){download(filteredLogs.value.map(l=>l.join(' ')).join('\n'),'synthetic-execution.log','text/plain')}
async function copyOutput(){try{await navigator.clipboard.writeText(JSON.stringify(outputValue.value,null,2));copied.value=true}catch{notify('剪贴板不可用，请下载JSON')}}
function downloadOutput(){download(JSON.stringify(outputValue.value,null,2),'synthetic-output.json')}
function enrollAgent(){agentRows.value.push({id:'demo-agent-'+(agentRows.value.length+1),name:enrollDevice.value,version:'0.2.0',state:'PENDING',channel:'mTLS',heartbeat:'未连接',tasks:0,certificate:'待签发',rack:'未采集'});agentDialog.value=false}
function keyboard(e:KeyboardEvent){if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();searchOpen.value=true}if(e.key==='Escape'){searchOpen.value=false;notifications.value=false;agentDetail.value=null}}
watch([query,namespace,targetFilter,flowState,project],()=>{pageNumber.value=1;viewSaved.value=false});
watch([targetSearch,targetState],()=>targetPage.value=1);
watch([agentSearch,agentState],()=>agentPage.value=1);
onMounted(()=>{try{const saved=JSON.parse(sessionStorage.getItem('keel-jobs-preview-view')||'null');if(saved){query.value=saved.query||'';namespace.value=saved.namespace||'';targetFilter.value=saved.target||'';flowState.value=saved.state||''}}catch{/* Preview preferences may be cleared by the browser. */}window.addEventListener('hashchange',syncRoute);window.addEventListener('keydown',keyboard);syncRoute()});onUnmounted(()=>{window.removeEventListener('hashchange',syncRoute);window.removeEventListener('keydown',keyboard);clearTimeout(feedbackTimer);clearTimeout(refreshTimer)});
const ExecutionList=defineComponent({props:{filter:{type:String,default:'all'}},emits:['open'],setup(props,{emit}){const search=ref('');const rows=computed(()=>Array.from({length:8},(_,i)=>({id:i===0?executionID.value:'demo-exec-'+['91ca','729f','26a8','4da3','61f1','5e82','182a'][i-1],flow:flows[i%flows.length].name,state:i===0?execState.value:i===1?'RUNNING':i===3?'FAILED':'SUCCESS',targets:32,duration:i===1?'进行中':'24.4s',time:['14:32:06','14:31:42','14:02:17','13:40:09','12:18:44','11:09:23','10:30:01','09:15:06'][i]})).filter(r=>(props.filter==='all'||props.filter==='running'&&r.state==='RUNNING'||props.filter==='failed'&&r.state==='FAILED')&&[r.id,r.flow].join(' ').includes(search.value)));return()=>h('div',{class:'jp-execution-catalog'},[h('div',{class:'jp-filters'},[h(KsInput,{modelValue:search.value,'onUpdate:modelValue':(v:string)=>search.value=v,placeholder:'搜索执行或Flow',clearable:true}),h('span',{class:'jp-grow'}),h('span',{class:'jp-muted'},rows.value.length+' 条执行记录')]),h(KsDataTable,{data:rows.value,total:rows.value.length,selectable:false,pageSize:25,fitHeight:true,rowKey:'id','onRow-click':(row:any)=>emit('open',row)},{default:()=>[h(KsTableColumn,{label:'Execution / Flow',minWidth:290},{default:({row}:any)=>h('div',{class:'jp-exec-title'},[h('button',{class:'jp-row-title',onClick:()=>emit('open',row)},row.flow),h('code',row.id)])}),h(KsTableColumn,{prop:'time',label:'开始时间',minWidth:150},{default:({row}:any)=>h('span',[row.time,h('small','2026-11-01')])}),h(KsTableColumn,{label:'状态',width:160},{default:({row}:any)=>h(KsExecutionStatus,{status:row.state,size:'small'})}),h(KsTableColumn,{label:'目标结果',minWidth:160},{default:({row}:any)=>h('div',[h('b','32 targets'),h('small',row.state==='FAILED'?'29 成功 / 2 失败 / 1 阻断':row.state==='RUNNING'?'16 成功 / 16 运行中':'32 成功')])}),h(KsTableColumn,{prop:'duration',label:'耗时',width:110}),h(KsTableColumn,{label:'来源',width:130},{default:()=>h('span',{class:'jp-target-tag'},'Manual')}),h(KsTableColumn,{label:'版本',width:80},{default:()=>h('code','rev 12')})]})])}});
</script>
